// V40 Live Sync provision: UI/design remains unchanged; only persistence/sync is added.
const LIVE_SYNC_CONFIG={
  apiBase:(window.NMRC_INVENTORY_API_BASE||'/api').replace(/\/$/,''),
  driveBackupUrl:window.NMRC_INVENTORY_DRIVE_BACKUP_URL||'',
  pollMs:Number(window.NMRC_INVENTORY_SYNC_POLL_MS||1500)
};
let liveSyncReady=false,liveSyncBusy=false,liveSyncTimer=null;
async function liveSyncPull(){if(!LIVE_SYNC_CONFIG.apiBase||liveSyncBusy)return;liveSyncBusy=true;try{const r=await fetch(LIVE_SYNC_CONFIG.apiBase+'/state',{headers:{'x-aurion-api-key':window.NMRC_INVENTORY_API_KEY||''}});if(!r.ok)return;const j=await r.json();if(j.ok&&j.state&&typeof j.state==='object'){state={...state,...j.state,records:{...state.records,...(j.state.records||{})}};Object.keys(BASE_REPORTS).forEach(k=>state.records[k] ||= []);state.reportDefs ||= {};state.stations ||= [];state.equipmentMaster ||= [];reports=deepClone(BASE_REPORTS);(state.dynamic||[]).forEach(k=>{if(state.reportDefs[k])reports[k]=state.reportDefs[k]});applyStandardFields();localStorage.setItem('aurion_state_v18',JSON.stringify(state));if(currentUser){renderNav();renderDashboard();if(current==='summary')renderReport();else if(document.querySelector('#app:not(.hidden)'))renderReport();renderLocation();}}liveSyncReady=true}catch(e){console.warn('Live sync pull failed',e)}finally{liveSyncBusy=false}}
function liveSyncPush(){if(!LIVE_SYNC_CONFIG.apiBase)return;clearTimeout(liveSyncPush._t);liveSyncPush._t=setTimeout(async()=>{try{const r=await fetch(LIVE_SYNC_CONFIG.apiBase+'/state',{method:'PUT',headers:{'content-type':'application/json','x-aurion-api-key':window.NMRC_INVENTORY_API_KEY||''},body:JSON.stringify({state,clientId:storageGet('aurion_client_id','')})});if(!r.ok)throw new Error('HTTP '+r.status);liveSyncReady=true}catch(e){console.warn('Live sync push failed',e)}},50)}
async function backupToGoogleDrive(){if(!LIVE_SYNC_CONFIG.driveBackupUrl)return alert('Google Drive backup URL is not configured yet. Add NMRC_INVENTORY_DRIVE_BACKUP_URL in config.js.');try{const r=await fetch(LIVE_SYNC_CONFIG.driveBackupUrl,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({filename:'NMRC Inventory_Final_Backup.json',state,updatedAt:new Date().toISOString()})});if(!r.ok)throw new Error('Backup endpoint returned '+r.status);alert('Google Drive backup sent successfully.')}catch(e){alert('Google Drive backup failed: '+e.message)}}
function openFinalSummaryExcel(){exportExcel('summary')}

const BASE_REPORTS={
 station:{title:'Station AG Inspection',fields:['Station Name','Equipment Type','Equipment Name','Equipment Number','Equipment Serial Number','G7 Status','Transaction File Pending','Equipment Photo']},
 pm:{title:'PM Checklist',fields:['Date','Agent','Station','Serial Number','Checklist Item','Status','Remarks']},
 failure:{title:'Failure Entry',fields:['Date','Time','Agent','Station','Serial Number','Failure Type','L1','PCR','D1','Status','Remarks']},
 material:{title:'Material Entry',fields:['Date','Agent','Station','Material','Quantity','Serial Number','Remarks']},
 inventory:{title:'Inventory Entry',fields:['Date','Agent','Station','Material','Opening','Received','Issued','Closing','Serial Number']},
 addinventory:{title:'Add New Inventory',fields:['Date','Material','Unit','Opening Stock','Added Quantity','Serial Number','Remarks']},
 summary:{title:'Final Summary Report',fields:['Date','Date & Time','Agent','Employee ID / User Name','Station','Product Name','Serial Number','Part / Product Photo','Latitude','Longitude','Map URL','Entry Photo','Failure Count','L1 Faulty','PCR Faulty','D1 Faulty','Material Quantity','Inventory Closing','Remarks']},
ccr:{title:'CCR Management',fields:['Name','Complaint Received Date/Time','Customer Gmail','App','Amount','Transaction Date/Time','UPI ID','UTR','UPI Transaction ID','App Transaction ID','Payment Method','Transaction Status','Reference ID','Reply Required','Reply To Gmail','Reply Subject','Reply Message','Replied By','Reply Date & Time','Reply Status','Resolution Status']}
};
const STANDARD_ENTRY_FIELDS=['Date','Date & Time','Agent','Employee ID / User Name','Station','Product Name','Serial Number','Part / Product Photo','Latitude','Longitude','Map URL','Entry Photo','Remarks'];
function applyStandardFields(){Object.keys(reports).forEach(k=>{if(k==='summary'||k==='location'||k==='ccr')return;if(k==='station'){reports[k].fields=['Station Name','Equipment Type','Equipment Name','Equipment Number','Equipment Serial Number','G7 Status','Transaction File Pending','Equipment Photo'];return}const specific=reports[k].fields||[];reports[k].fields=[...STANDARD_ENTRY_FIELDS,...specific.filter(f=>!STANDARD_ENTRY_FIELDS.includes(f))]})}
const STATIC_ROLES=[['station','Station AG Inspection'],['pm','PM Checklist'],['failure','Failure Entry'],['material','Material Entry'],['inventory','Inventory Entry'],['addinventory','Add New Inventory'],['summary','Final Summary Report'],['location','Agent Location History'],['ccr','CCR Transaction Screenshot Report']];
function deepClone(v){return JSON.parse(JSON.stringify(v))}
let reports=deepClone(BASE_REPORTS);
let state={records:{},locations:[],dynamic:[],users:[],activities:[],settings:{},stations:[],equipmentMaster:[]};
try{const raw=localStorage.getItem('aurion_state_v18'); if(raw){const parsed=JSON.parse(raw); if(parsed&&typeof parsed==='object') state={...state,...parsed};}}catch(e){console.warn('State load failed; starting clean state',e)}
Object.keys(BASE_REPORTS).forEach(k=>state.records[k] ||= []);
(state.dynamic||[]).forEach(k=>{if(k&&state.reportDefs?.[k])reports[k]=state.reportDefs[k];});
state.reportDefs ||= {}; state.stations ||= []; state.equipmentMaster ||= []; applyStandardFields();
let current='station',editIndex=null,userEditIndex=null,currentUser=null;
const $=id=>document.getElementById(id);
function save(){localStorage.setItem('aurion_state_v18',JSON.stringify(state));liveSyncPush();}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function attr(v){return esc(v).replace(/\n/g,' ')}
function isAdmin(){return currentUser?.id==='admin'}
function permsFor(user,key){if(isAdmin())return {view:true,add:true,edit:true,delete:true}; if(key==='location')return {view:true,add:false,edit:false,delete:false}; return user?.permissions?.[key]||{view:false,add:false,edit:false,delete:false};}
function roleLabel(key){return reports[key]?.title||STATIC_ROLES.find(x=>x[0]===key)?.[1]||key}
function storageGet(key, fallback=''){try{return localStorage.getItem(key)??fallback}catch(e){return fallback}}
function storageSet(key,value){try{localStorage.setItem(key,value);return true}catch(e){return false}}
async function login(){
 try{
  // Pull the latest central users before authentication so APKs can use users created/updated by Admin.
  if(LIVE_SYNC_CONFIG.apiBase){ try{ await liveSyncPull(); }catch(_){} }
  clearInterval(liveSyncTimer); liveSyncTimer=setInterval(()=>liveSyncPull(), LIVE_SYNC_CONFIG.pollMs);
  const userEl=$('username'),passEl=$('password');
  const u=String(userEl?.value||'').trim(), p=String(passEl?.value||'');
  if(!u||!p){alert('Please enter Username and Password.');return false}
  let found=null;
  if(u.toLowerCase()==='admin'){ const configuredAdminPassword=String(state.adminPassword||'').trim(); const localAdminPassword=String(storageGet('admin_password','')).trim(); const adminPasswordOk=configuredAdminPassword ? p===configuredAdminPassword : (p===localAdminPassword || p==='admin123'); if(adminPasswordOk) found={id:'admin',name:'Admin',mobile:storageGet('admin_mobile',''),photo:storageGet('admin_photo',''),role:'Admin'}; }
  else found=(state.users||[]).find(x=>String(x?.id||'').trim().toLowerCase()===u.toLowerCase()&&String(x?.password??'')===p);
  if(!found){alert('Invalid username or password.');return false}
  const now=new Date().toISOString();
  if(found.id==='admin') storageSet('admin_last_login',now); else {found.lastLogin=now;save()}
  currentUser={...found,lastLogin:now};
  applyCCRRolePermissions(currentUser);
  storageSet('aurion_session_v1',JSON.stringify(currentUser));
  resetIdleLogoutTimer();
  const lp=$('loginPage'), app=$('app');
  if(!lp||!app) throw new Error('Login screen not found');
  lp.classList.add('hidden'); app.classList.remove('hidden');
  setHeader(); renderNav(); renderDashboard(); showDashboard(); ccrAutoPoll();
  return false;
 }catch(e){console.error('Login failed',e);alert('Login error: '+(e?.message||'Please try again.'));return false}
}
window.login=login;

['click','touchstart','keydown','mousemove','scroll'].forEach(ev=>document.addEventListener(ev,markUserActivity,{passive:true}));
document.addEventListener('DOMContentLoaded',()=>{
  const btn=$('loginBtn');
  if(btn){
    btn.type='button';
    btn.onclick=(e)=>{e.preventDefault();login();};
  }
  const pass=$('password');
  if(pass) pass.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();login();}});
  try{
    const raw=storageGet('aurion_session_v1','');
    if(raw){
      const saved=JSON.parse(raw);
      if(saved&&saved.id){
        currentUser=saved;
        applyCCRRolePermissions(currentUser);
        $('loginPage')?.classList.add('hidden');
        $('app')?.classList.remove('hidden');
        setHeader();renderNav();renderDashboard();showDashboard();resetIdleLogoutTimer();
      }
    }
  }catch(e){storageSet('aurion_session_v1','');console.warn('Session restore failed',e)}
});
function openForgotPassword(){$('forgotModal')?.classList.remove('hidden');$('forgotStep1')?.classList.remove('hidden');$('forgotStep2')?.classList.add('hidden');$('forgotUser').value='';$('forgotOtp').value='';$('forgotNewPassword').value='';$('forgotMsg').textContent='';setTimeout(()=>$('forgotUser')?.focus(),50)}
function closeForgotPassword(){$('forgotModal')?.classList.add('hidden')}
let forgotContext=null;
function maskMobile(m){const x=String(m||'').replace(/\D/g,'');return x.length>=4?'******'+x.slice(-4):'the registered mobile number'}
function requestForgotOtp(){const id=$('forgotUser').value.trim();if(!id)return alert('Enter Employee ID / Username.');const user=state.users.find(x=>String(x.id).toLowerCase()===id.toLowerCase());if(!user)return alert('Employee ID not found.');if(!user.mobile)return alert('No mobile number is registered for this user.');const otp=String(Math.floor(1000+Math.random()*9000));forgotContext={id:user.id,otp,expires:Date.now()+5*60*1000};console.log('NMRC Inventory demo OTP:',otp);$('forgotMasked').textContent=`A 4 digit OTP was generated for ${maskMobile(user.mobile)}.`;$('forgotStep1').classList.add('hidden');$('forgotStep2').classList.remove('hidden');$('forgotMsg').textContent='SMS gateway is not connected in this test ZIP. Production API hook is ready; connect an SMS provider to deliver this OTP by SMS.';alert(`Test OTP: ${otp}\n\nConnect the SMS provider API for real SMS delivery to the registered mobile number.`)}
function verifyForgotOtp(){const otp=$('forgotOtp').value.trim();const pass=$('forgotNewPassword').value;if(!/^\d{4}$/.test(otp))return alert('OTP must be exactly 4 digits.');if(!pass)return alert('Enter a new password.');if(!forgotContext||Date.now()>forgotContext.expires)return alert('OTP expired. Request a new OTP.');if(otp!==forgotContext.otp)return alert('Invalid OTP.');const user=state.users.find(x=>x.id===forgotContext.id);if(!user)return alert('User not found.');user.password=pass;save();forgotContext=null;alert('Password reset successfully. Please login with your new password.');closeForgotPassword()}
function changeAdminPassword(e){e.preventDefault();if(!isAdmin())return alert('Admin access required.');const cur=$('adminCurrentPassword')?.value||'';const np=$('adminNewPassword')?.value||'';const cp=$('adminConfirmPassword')?.value||'';const actual=String(state.adminPassword||storageGet('admin_password','admin123'));if(cur!==actual)return alert('Current Admin password is incorrect.');if(np.length<4)return alert('New password must be at least 4 characters.');if(np!==cp)return alert('New password and confirmation do not match.');state.adminPassword=np;storageSet('admin_password',np);save();$('adminCurrentPassword').value='';$('adminNewPassword').value='';$('adminConfirmPassword').value='';if($('adminPasswordMsg'))$('adminPasswordMsg').textContent='Admin password changed successfully. Use the new password at next login.';alert('Admin password changed successfully.');}
function togglePassword(){const p=$('password');p.type=p.type==='password'?'text':'password'}
let idleLogoutTimer=null;
function resetIdleLogoutTimer(){
 clearTimeout(idleLogoutTimer);
 if(!currentUser)return;
 idleLogoutTimer=setTimeout(()=>{if(currentUser){alert('Session expired after 3 minutes of inactivity. Please login again.');logout();}},180000);
}
function markUserActivity(){if(currentUser)resetIdleLogoutTimer()}
function logout(){clearTimeout(idleLogoutTimer);currentUser=null;try{localStorage.removeItem('aurion_session_v1')}catch(_){} clearInterval(liveSyncTimer); liveSyncTimer=null; $('app')?.classList.add('hidden'); $('loginPage')?.classList.remove('hidden'); if($('password'))$('password').value=''; closeSidebar();}
function adminLogoSvg(){return 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"%3E%3Crect width="100" height="100" rx="16" fill="%230a6574"/%3E%3Ctext x="50" y="62" text-anchor="middle" font-family="Arial,sans-serif" font-size="38" font-weight="800" fill="white"%3EAP%3C/text%3E%3C/svg%3E'}
function setHeader(){ const hn=$('headerName'); if(hn)hn.textContent=currentUser.name; const ha=$('headerAvatar'); if(ha)ha.src=isAdmin()?adminLogoSvg():currentUser.photo||avatarSvg(); const dd=$('adminDropdown'); if(!dd)return; dd.innerHTML=`<div class="admin-user"><b>${esc(currentUser.name)}</b><div>Employee ID: ${esc(currentUser.id)}</div><div>Mobile: ${esc(currentUser.mobile||'Not set')}</div><div>Role: ${esc(currentUser.role||'Agent')}</div><div>Last Login: ${currentUser.lastLogin?esc(new Date(currentUser.lastLogin).toLocaleString()):'—'}</div>${isAdmin()?'':'<div class="photo-note">Profile photo managed by Admin</div>'}</div>${isAdmin()?'<button type="button" onclick="showSettings();closeAdminMenu()">🔐 Change Admin Password</button>':''}<button onclick="logout()">Logout</button>`; if($('sessionInfo'))$('sessionInfo').innerHTML=`<p><b>${esc(currentUser.name)}</b> • ${esc(currentUser.id)} • Logged in ${esc(new Date(currentUser.lastLogin).toLocaleString())}</p>`;}
function avatarSvg(){return 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"%3E%3Ccircle cx="50" cy="50" r="50" fill="%23dfe6ee"/%3E%3Ccircle cx="50" cy="40" r="17" fill="%23899"/%3E%3Cpath d="M20 85c4-20 56-20 60 0" fill="%23899"/%3E%3C/svg%3E'}
function changeAdminPhoto(e){if(!isAdmin())return;const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{localStorage.setItem('admin_photo',r.result);currentUser.photo=r.result;setHeader()};r.readAsDataURL(f)}
let cameraStream=null,cameraTarget=null;
async function openCamera(target){
 cameraTarget=target;
 const modal=$('cameraModal'),video=$('cameraVideo'),hint=$('cameraHint');
 if(!modal||!video)return;
 modal.classList.add('show'); hint.textContent='Starting camera…';
 try{
  if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia) throw new Error('Camera API unavailable. Open this portal on HTTPS or localhost.');
  cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:target==='employee'?'user':'environment'},audio:false});
  video.srcObject=cameraStream; await video.play(); hint.textContent='Camera ready. Tap Capture Photo.';
 }catch(err){hint.textContent='Camera could not start: '+err.message;}
}
function closeCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}const v=$('cameraVideo');if(v)v.srcObject=null;$('cameraModal')?.classList.remove('show');cameraTarget=null}
function captureCameraPhoto(){
 const v=$('cameraVideo'),c=$('cameraCanvas');
 if(!cameraStream||!v||!c||!v.videoWidth){alert('Camera is not ready yet.');return}
 c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0,c.width,c.height);
 const data=c.toDataURL('image/jpeg',.88);
 if(cameraTarget==='employee'){const el=$('employeePhotoData');if(el)el.value=data;const prev=$('employeePhotoPreview');if(prev)prev.innerHTML=`<img src="${data}" alt="Employee">`}
 if(cameraTarget==='entry'){const el=$('entryPhoto');if(el)el.value=data;const prev=$('entryPhotoPreview');if(prev)prev.innerHTML=`<img src="${data}" alt="Entry">`}
 closeCamera();
}
function toggleAdminMenu(){const d=$('adminDropdown');if(d)d.classList.toggle('show')}
function toggleSidebar(){$('sidebar').classList.toggle('open');$('overlay').classList.toggle('show')}
function closeSidebar(){$('sidebar').classList.remove('open');$('overlay').classList.remove('show')}
const CCR_REPORT_KEY='ccr';
let ccrView='main';
let ccrGmailBusy=false,ccrGmailTimer=null;
const CCR_ROLE_OPTIONS=['CCR Admin','CCR Manager','CCR User','CCR Reply User','CCR View Only'];
function getCCRRole(user){return String(user?.ccrRole||'').trim();}
function getCCRRoles(user){return Array.isArray(user?.ccrRoles)&&user.ccrRoles.length?user.ccrRoles:(getCCRRole(user)?[getCCRRole(user)]:[]);}
const CCR_REPORT_KEYS={management:'management',received:'received',status:'status',final:'final'};
function applyCCRRolePermissions(user){
  if(!user)return;
  user.permissions ||= {};
  user.ccrPermissions ||= {};
  const legacy=user.permissions[CCR_REPORT_KEY];
  if(legacy && !Object.keys(user.ccrPermissions).length){
    Object.keys(CCR_REPORT_KEYS).forEach(k=>user.ccrPermissions[k]={...legacy});
  }
}
function ccrPerms(user,key){
  if(isAdmin())return {view:true,add:true,edit:true,delete:true};
  return user?.ccrPermissions?.[key]||{view:false,add:false,edit:false,delete:false};
}
function ccrViewRows(rows){
  if(ccrView==='received') return rows.filter(r=>String(r['Reply Status']||'Not Replied')==='Not Replied');
  if(ccrView==='status') return rows.filter(r=>String(r['Reply Status']||'Not Replied')==='Not Replied' || String(r['Resolution Status']||'Pending')==='Pending');
  return rows;
}
function openCCRView(view){
  if(!currentUser||!ccrPerms(currentUser,view||'management').view){alert('You do not have View permission for this CCR report.');return}
  ccrView=view||'main'; current=CCR_REPORT_KEY; editIndex=null; showPage('report'); closeSidebar(); renderReport();
}
function toggleCCRMenu(){const d=$('ccrSub');if(d)d.classList.toggle('hidden');}

function isCCRUser(){return !!currentUser && !isAdmin() && Object.keys(CCR_REPORT_KEYS).some(k=>ccrPerms(currentUser,k).view);}
function ccrVisibleRows(){const rows=state.records[CCR_REPORT_KEY]||[];return isAdmin()?rows:rows.filter(x=>String(x?._userId||'')===String(currentUser?.id||''));}
function ccrReplyFor(row){const status=String(row?.['Transaction Status']||row?.Status||'').toLowerCase();const name=String(row?.Name||'').trim();const amount=String(row?.Amount||'').trim();const greeting=name?`Dear ${name},`:'Dear Customer,';if(status.includes('success'))return `${greeting}\n\nWe have received your payment${amount?` of ${amount}`:''} successfully. Thank you.`;if(status.includes('fail'))return `${greeting}\n\nWe could not confirm the payment${amount?` of ${amount}`:''}. Please share the transaction screenshot or UTR number so we can check it.`;if(status.includes('pending'))return `${greeting}\n\nYour payment${amount?` of ${amount}`:''} is currently pending. We are checking the transaction status and will update you once it is confirmed.`;return `${greeting}\n\nWe are reviewing your transaction details. Please share any missing transaction reference or UTR number if available.`;}
function ccrSubject(row){const status=String(row?.['Transaction Status']||row?.Status||'').trim();return status?`Payment ${status} - Transaction Review`:'Transaction Review';}
function ccrGmailUrl(row){const to=String(row?.['Reply To Gmail']||row?.Gmail||'').trim();if(!to)return '';const subject=String(row?.['Reply Subject']||ccrSubject(row));const body=String(row?.['Reply Message']||ccrReplyFor(row));return `https://mail.google.com/mail/?view=cm&fs=1&to=${encodeURIComponent(to)}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;}
async function gmailStatus(){try{const r=await fetch((LIVE_SYNC_CONFIG.apiBase||'/api')+'/gmail/status',{headers:{'x-aurion-api-key':window.NMRC_INVENTORY_API_KEY||''}});return r.ok?await r.json():{connected:false,configured:false};}catch(_){return {connected:false,configured:false}}}
async function connectCCRMail(){const st=await gmailStatus();if(!st.configured)return alert('Gmail OAuth is not configured on the portal worker yet. Add the Google OAuth Client ID/Secret and redirect URI first.');if(st.connected)return alert(`Gmail already connected${st.email?': '+st.email:''}.`);const r=await fetch((LIVE_SYNC_CONFIG.apiBase||'/api')+'/gmail/connect',{headers:{'x-aurion-api-key':window.NMRC_INVENTORY_API_KEY||''}});const j=await r.json();if(j.url)window.location.href=j.url;else alert(j.error||'Unable to start Gmail connection.');}
async function processGmailMessages(silent=false){if(ccrGmailBusy)return;ccrGmailBusy=true;const status=$('ccrGmailStatus');try{const st=await gmailStatus();if(!st.connected){if(!silent&&st.configured)alert('Please connect the complaint Gmail first.');return;}if(status)status.textContent='Checking Gmail…';const r=await fetch((LIVE_SYNC_CONFIG.apiBase||'/api')+'/gmail/messages?max=25',{headers:{'x-aurion-api-key':window.NMRC_INVENTORY_API_KEY||''}});const j=await r.json();if(!j.ok)throw new Error(j.error||'Gmail read failed');let added=0;const ack=[];for(const m of (j.messages||[])){try{let text=`${m.subject||''}\n${m.from||''}\n${m.text||''}`;for(const img of (m.images||[])){try{const ar=await fetch(`${LIVE_SYNC_CONFIG.apiBase||'/api'}/gmail/attachment?messageId=${encodeURIComponent(m.id)}&attachmentId=${encodeURIComponent(img.attachmentId)}`,{headers:{'x-aurion-api-key':window.NMRC_INVENTORY_API_KEY||''}});const aj=await ar.json();if(aj?.data&&typeof Tesseract!=='undefined'){const bin=atob(String(aj.data).replace(/-/g,'+').replace(/_/g,'/'));const bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));const blob=new Blob([bytes],{type:img.mimeType||'image/jpeg'});const ocr=await Tesseract.recognize(blob,'eng');text+='\n'+(ocr?.data?.text||'');}}catch(e){console.warn('Gmail attachment OCR failed',img.filename,e)}}let row=ccrParseText(text,`Gmail: ${m.subject||m.id}`);const sender=(String(m.from||'').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)||[])[0]||'';if(sender){row['Customer Gmail']=sender;}if(!row['Reply To Gmail'])row['Reply To Gmail']=sender;row['Reply Required']=row.Gmail?'Yes':'No';row['Reply Subject']=ccrSubject(row);row['Reply Message']=ccrReplyFor(row);row.Source=`Gmail: ${m.subject||m.id}`;row._gmailMessageId=m.id;row._gmailDate=m.date||'';row._userId=currentUser.id;row._userName=currentUser.name;row._savedAt=new Date().toISOString();row['Reply Status']='Not Replied';row['Resolution Status']='Pending';state.records[CCR_REPORT_KEY] ||= [];state.records[CCR_REPORT_KEY].push(row);added++;ack.push(m.id);}catch(e){console.warn('Gmail complaint processing failed',m.id,e)}}if(ack.length){await fetch((LIVE_SYNC_CONFIG.apiBase||'/api')+'/gmail/ack',{method:'POST',headers:{'content-type':'application/json','x-aurion-api-key':window.NMRC_INVENTORY_API_KEY||''},body:JSON.stringify({ids:ack})});state.activities.push(`CCR imported ${added} new Gmail complaint${added===1?'':'s'} by ${currentUser.name}`);save();renderCCRReport();}if(status)status.textContent=`Gmail: ${added} new complaint${added===1?'':'s'} imported${st.email?' • '+st.email:''}.`;if(!silent&&!added)status.textContent=`Gmail: no new complaints${st.email?' • '+st.email:''}.`;}catch(e){console.warn('CCR Gmail sync failed',e);if(status)status.textContent='Gmail sync error: '+e.message;}finally{ccrGmailBusy=false;}}
function ccrAutoPoll(){clearInterval(ccrGmailTimer);if(currentUser&&ccrPerms(currentUser,'received').view)processGmailMessages(true);ccrGmailTimer=setInterval(()=>{if(currentUser&&ccrPerms(currentUser,'received').view)processGmailMessages(true)},30000);}
function ccrMarkReply(i){const rows=state.records[CCR_REPORT_KEY]||[],row=rows[i];if(!row)return;if(!['CCR Admin','CCR Manager','CCR User','CCR Reply User'].includes(getCCRRole(currentUser))&&!isAdmin())return alert('Reply permission is not granted.');row['Reply Status']='Reply Sent';row['Replied By']=currentUser.name||currentUser.id;row['Reply Date & Time']=new Date().toLocaleString();if(!row['Resolution Status']||row['Resolution Status']==='Pending')row['Resolution Status']='Pending';save();renderCCRReport();}
function ccrSetResolution(i,status){const rows=state.records[CCR_REPORT_KEY]||[],row=rows[i];if(!row)return;if(!isAdmin()&&!['CCR Admin','CCR Manager','CCR User'].includes(getCCRRole(currentUser)))return alert('Resolution permission is not granted.');row['Resolution Status']=status;save();renderCCRReport();}
function renderCCRReport(){
 const p=ccrPerms(currentUser,ccrView==='main'?'management':ccrView==='received'?'received':ccrView==='status'?'status':'final'), allRows=ccrVisibleRows(), rows=ccrViewRows(allRows);
 const received=allRows.length;
 const pendingReply=allRows.filter(r=>String(r['Reply Required']||'').toLowerCase()==='yes'&&String(r['Reply Status']||'Not Replied')!=='Reply Sent').length;
 const replied=allRows.filter(r=>String(r['Reply Status']||'')==='Reply Sent').length;
 const resolved=allRows.filter(r=>String(r['Resolution Status']||'Pending')==='Resolved').length;
 const pendingResolution=allRows.filter(r=>String(r['Resolution Status']||'Pending')!=='Resolved').length;
 const upload=p.add?`<div class="panel ccr-upload-panel"><div class="form-head"><div><h3>Complaint Intake</h3><div class="muted">Connected Gmail is the primary source. Manual screenshot upload remains available as backup.</div></div><span class="admin-badge">CCR</span></div><div class="form-grid"><div class="field full"><div class="actions"><button class="btn primary" type="button" onclick="connectCCRMail()">Connect Complaint Gmail</button><button class="btn primary" type="button" onclick="processGmailMessages(false)">Check New Gmail Now</button><button class="btn gray" type="button" onclick="document.getElementById('ccrFiles').click()">Upload Screenshot Manually</button><span id="ccrGmailStatus" class="muted"></span></div></div><div class="field full"><input id="ccrFiles" type="file" accept="image/*" multiple style="display:none" onchange="processCCRFiles()"><div id="ccrOCRStatus" class="muted"></div></div></div></div>`:'';
 const cards=`<div class="cards"><div class="card"><div class="card-title">Total Complaints</div><div class="card-value">${received}</div></div><div class="card"><div class="card-title">New / Received</div><div class="card-value">${received}</div></div><div class="card"><div class="card-title">Pending Reply</div><div class="card-value">${pendingReply}</div></div><div class="card"><div class="card-title">Reply Sent</div><div class="card-value">${replied}</div></div><div class="card"><div class="card-title">Resolved</div><div class="card-value">${resolved}</div></div><div class="card"><div class="card-title">Pending Resolution</div><div class="card-value">${pendingResolution}</div></div></div>`;
 const employees={};
 allRows.forEach(r=>{const n=String(r._userName||r._userId||'Unassigned');employees[n] ||= {total:0,pending:0};employees[n].total++;if(String(r['Reply Status']||'Not Replied')!=='Reply Sent'||String(r['Resolution Status']||'Pending')!=='Resolved')employees[n].pending++;});
 const employeeRows=Object.entries(employees).map(([name,v])=>`<tr><td>${esc(name)}</td><td>${v.total}</td><td>${v.pending}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No CCR employee workload yet.</td></tr>';
 const employeePanel=`<div class="panel"><h3>CCR Team Workload</h3><table><thead><tr><th>Employee Name</th><th>Complaint Count</th><th>Pending Count</th></tr></thead><tbody>${employeeRows}</tbody></table></div>`;
 $('reportActions').innerHTML=`<button class="btn gray" onclick="exportExcel('${CCR_REPORT_KEY}')">Excel</button><button class="btn gray" onclick="exportPDF('${CCR_REPORT_KEY}')">PDF</button>`;
 const titles={main:'CCR Management',received:'Complaint Received',status:'Complaint Reply / Pending Status'};
 $('reportTitle').textContent=titles[ccrView]||'Final Summary';
 $('reportDesc').textContent=ccrView==='main'?'CCR team summary and workload dashboard.':'CCR workflow report';
 $('reportForm').innerHTML=ccrView==='main'?upload+cards+employeePanel:upload;
 if(ccrView==='main'){
   $('thead').innerHTML='';$('tbody').innerHTML='';
   return;
 }
 const heads=reports[CCR_REPORT_KEY].fields;
 $('thead').innerHTML='<tr>'+heads.map(f=>`<th>${esc(f)}</th>`).join('')+'<th>Actions</th></tr>';
 $('tbody').innerHTML=rows.map(row=>{const realIndex=(state.records[CCR_REPORT_KEY]||[]).indexOf(row);const gmail=ccrGmailUrl(row);return `<tr>${heads.map(f=>`<td>${esc(row[f]??'')}</td>`).join('')}<td><button class="btn gray small-btn" onclick="ccrCheck(${realIndex})">${row._checked==='Yes'?'✓ Checked':'✓ Check'}</button> ${p.edit?`<button class="btn primary small-btn" onclick="editCCRRecord(${realIndex})">✏️ Edit</button>`:''} ${gmail?`<button class="btn primary small-btn" onclick="openCCRGmail(${realIndex})">Open Gmail</button>`:''} ${gmail&&row['Reply Status']!=='Reply Sent'&&p.edit?`<button class="btn gray small-btn" onclick="ccrMarkReply(${realIndex})">Mark Reply Sent</button>`:''} ${p.edit?(row['Resolution Status']==='Pending'?`<button class="btn gray small-btn" onclick="ccrSetResolution(${realIndex},'Resolved')">Resolve</button>`:`<button class="btn gray small-btn" onclick="ccrSetResolution(${realIndex},'Pending')">Set Pending</button>`):''} ${p.delete?`<button class="btn danger small-btn" onclick="deleteCCRRecord(${realIndex})">Delete</button>`:''}</td></tr>`}).join('')||`<tr><td colspan="${heads.length+1}" class="empty">No CCR complaints yet.</td></tr>`;
 ccrAutoPoll();
}
function ccrCheck(i){const row=(state.records[CCR_REPORT_KEY]||[])[i];if(!row)return;row._checked=row._checked==='Yes'?'No':'Yes';save();renderCCRReport();}
function editCCRRecord(i){const row=(state.records[CCR_REPORT_KEY]||[])[i];if(!row)return;if(!ccrPerms(currentUser,ccrView==='final'?'final':'status').edit)return alert('Edit permission is not granted.');editIndex=i;const heads=reports[CCR_REPORT_KEY].fields; $('reportForm').innerHTML=`<div class="panel"><h3>Edit CCR Complaint</h3><div class="form-grid">${heads.map(f=>`<div class="field"><label>${esc(f)}</label><input data-ccr-edit="${attr(f)}" value="${attr(row[f]||'')}"></div>`).join('')}<div class="field full"><div class="actions"><button class="btn primary" type="button" onclick="saveCCREdit()">✓ Save Changes</button><button class="btn gray" type="button" onclick="editIndex=null;renderCCRReport()">Cancel</button></div></div></div></div>`;}
function saveCCREdit(){if(editIndex===null)return;const row=(state.records[CCR_REPORT_KEY]||[])[editIndex];if(!row)return;document.querySelectorAll('[data-ccr-edit]').forEach(el=>row[el.dataset.ccrEdit]=el.value);row['Reply Subject'] ||= ccrSubject(row);row['Reply Message'] ||= ccrReplyFor(row);save();editIndex=null;renderCCRReport();}
function openCCRGmail(i){const row=(state.records[CCR_REPORT_KEY]||[])[i];const url=ccrGmailUrl(row);if(!url)return alert('Customer Gmail address is not available.');window.open(url,'_blank','noopener');}
function deleteCCRRecord(i){if(!ccrPerms(currentUser,'final').delete)return alert('Delete permission is not granted.');const row=(state.records[CCR_REPORT_KEY]||[])[i];if(!row)return;if(!isAdmin()&&String(row._userId||'')!==String(currentUser?.id||''))return alert('You can delete only your own CCR records.');if(!confirm('Delete this CCR transaction record?'))return;state.records[CCR_REPORT_KEY].splice(i,1);save();renderCCRReport();}
function ccrPick(text,patterns){for(const re of patterns){const m=text.match(re);if(m&&m[1])return m[1].trim()}return ''}
function ccrClean(v){return String(v||'').replace(/[\u200b\u200c\u200d]/g,'').replace(/\s{2,}/g,' ').trim()}
function ccrNormalizeDate(v){const s=ccrClean(v);let m=s.match(/\b(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})\b/);if(m){let y=m[3];if(y.length===2)y='20'+y;return `${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}-${y}`;}m=s.match(/\b(\d{1,2})\s+(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\s+(\d{4})\b/i);if(m){const months={jan:'01',feb:'02',mar:'03',apr:'04',may:'05',jun:'06',jul:'07',aug:'08',sep:'09',oct:'10',nov:'11',dec:'12'};return `${m[1].padStart(2,'0')}-${months[m[2].slice(0,3).toLowerCase()]}-${m[3]}`;}return ''}
function ccrParseText(text,filename){
 const t=String(text||'').replace(/\r/g,'\n');
 const email=(t.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig)||[])[0]||'';
 const app=/super\.?money/i.test(t)?'Super.Money':/google\s*pay|gpay/i.test(t)?'Google Pay':/phonepe/i.test(t)?'PhonePe':/paytm/i.test(t)?'Paytm':/amazon\s*pay/i.test(t)?'Amazon Pay':/bhim/i.test(t)?'BHIM':/mobikwik/i.test(t)?'MobiKwik':/bank|netbanking|internet banking/i.test(t)?'Bank': '';
 const amount=ccrPick(t,[/(?:amount|paid|sent|received|payment)\s*(?:is|of|:)?\s*(?:₹|rs\.?|inr)\s*([0-9,]+(?:\.\d{1,2})?)/i,/(?:₹|rs\.?|inr)\s*([0-9,]+(?:\.\d{1,2})?)/i]);
 const date=ccrNormalizeDate(ccrPick(t,[/(?:date|on)\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4})/i,/\b(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4})\b/]));
 const time=ccrPick(t,[/(?:time|at)\s*[:\-]?\s*(\d{1,2}:\d{2}\s*(?:am|pm)?)/i,/\b(\d{1,2}:\d{2}\s*(?:am|pm))\b/i]);
 const upi=ccrPick(t,[/(?:upi\s*id|vpa)\s*[:\-]?\s*([A-Za-z0-9._-]+@[A-Za-z0-9.-]+)/i,/\b([A-Za-z0-9._-]{2,}@[A-Za-z0-9.-]{2,})\b/]);
 const utr=ccrPick(t,[/(?:utr|rrn|bank\s*reference(?:\s*number)?|utr\s*number)\s*[:#\-]?\s*([A-Z0-9]{6,30})/i]);
 const upiTxn=ccrPick(t,[/(?:upi\s*(?:transaction|txn)\s*id|upi\s*transaction\s*id)\s*[:#\-]?\s*([A-Z0-9]{6,40})/i]);
 const appTxn=ccrPick(t,[/(?:app\s*transaction\s*id|transaction\s*id|txn\s*id)\s*[:#\-]?\s*([A-Z0-9]{6,50})/i]);
 const ref=ccrPick(t,[/(?:reference\s*(?:id|number|no\.?))\s*[:#\-]?\s*([A-Z0-9]{5,40})/i]);
 const name=ccrPick(t,[/(?:paid\s*to|sent\s*to|received\s*from|recipient|receiver|merchant|beneficiary|name)\s*[:\-]?\s*([A-Za-z][A-Za-z .'-]{2,60})/i]);
 const payment=ccrPick(t,[/(?:payment\s*(?:method|mode)|paid\s*(?:via|from)|debit\s*from|credit\s*from)\s*[:\-]?\s*([^\n]{2,60})/i]);
 let status='';if(/payment\s*(?:was\s*)?successful|transaction\s*successful|successfully\s*paid|completed/i.test(t))status='Success';else if(/payment\s*failed|transaction\s*failed|failed/i.test(t))status='Failed';else if(/payment\s*pending|transaction\s*pending|pending/i.test(t))status='Pending';
 const savedAt=new Date().toISOString(); const row={'Name':ccrClean(name),'Complaint Received Date/Time':savedAt,'Customer Gmail':email,'App':app,'Amount':amount?`₹${amount.replace(/,/g,'')}`:'','Transaction Date/Time':[date,ccrClean(time)].filter(Boolean).join(' '),'UPI ID':ccrClean(upi),'UTR':ccrClean(utr),'UPI Transaction ID':ccrClean(upiTxn),'App Transaction ID':ccrClean(appTxn),'Payment Method':ccrClean(payment),'Transaction Status':status,'Reference ID':ccrClean(ref),'Reply Required':email?'Yes':'No','Reply To Gmail':email,'Reply Subject':'','Reply Message':'','Replied By':'','Reply Date & Time':'','Reply Status':'Not Replied','Resolution Status':'Pending','_userId':currentUser.id,'_userName':currentUser.name,'_savedAt':savedAt,'Source':filename||''};row['Reply Subject']=ccrSubject(row);row['Reply Message']=ccrReplyFor(row);return row;
}
async function processCCRFiles(){if(!ccrPerms(currentUser,'received').add)return alert('Add permission is not granted for Complaint Received.');const input=$('ccrFiles');const files=[...(input?.files||[])];if(!files.length)return alert('Please select one or more screenshots.');if(typeof Tesseract==='undefined')return alert('OCR library is still loading. Please wait a few seconds and try again.');const status=$('ccrOCRStatus');let done=0;for(const file of files){try{status.textContent=`Reading ${done+1} of ${files.length}: ${file.name}`;const result=await Tesseract.recognize(file,'eng',{logger:m=>{if(m.status==='recognizing text'&&m.progress)status.textContent=`Reading ${done+1} of ${files.length}: ${Math.round(m.progress*100)}%`}});const row=ccrParseText(result?.data?.text||'',file.name);state.records[CCR_REPORT_KEY] ||= [];state.records[CCR_REPORT_KEY].push(row);done++;}catch(e){console.warn('CCR OCR failed',file.name,e);}}if(done){state.activities.push(`CCR processed ${done} screenshot${done>1?'s':''} by ${currentUser.name}`);save();renderCCRReport();}status.textContent=`Completed: ${done} of ${files.length} screenshot${files.length>1?'s':''}.`;if(input)input.value='';}

function renderNav(){
 let h=`<a onclick="showDashboard()">⌂ <span>Dashboard</span></a>`;
 const ccrMenu=`<div class="master-block ccr-nav-block"><button type="button" class="master-toggle" onclick="toggleCCRMenu()">▦ <span>CCR Management</span><em id="ccrArrow">⌄</em></button><div id="ccrSub" class="master-sub hidden">${ccrPerms(currentUser,'management').view?'<a onclick="openCCRView(\'main\')">▦ <span>CCR Management</span></a>':''}${ccrPerms(currentUser,'received').view?'<a onclick="openCCRView(\'received\')">▤ <span>Complaint Received</span></a>':''}${ccrPerms(currentUser,'status').view?'<a onclick="openCCRView(\'status\')">▥ <span>Complaint Reply / Pending Status</span></a>':''}${ccrPerms(currentUser,'final').view?'<a onclick="openCCRView(\'final\')">▤ <span>Final Summary</span></a>':''}</div></div>`;
 if(isCCRUser()){h+=ccrMenu;$('nav').innerHTML=h;return}
 STATIC_ROLES.filter(x=>x[0]!=='summary'&&x[0]!=='location'&&x[0]!=='ccr').forEach(([k,n])=>{if(permsFor(currentUser,k).view)h+=`<a onclick="openReport('${k}')">▦ <span>${esc(n)}</span></a>`});
 if(permsFor(currentUser,'summary').view)h+=`<a onclick="openReport('summary')">▥ <span>Reports / Final Summary</span></a>`;
 if(permsFor(currentUser,'location').view)h+=`<a onclick="showLocation()">⌖ <span>Agent Location History</span></a>`;
 if(permsFor(currentUser,CCR_REPORT_KEY).view)h+=ccrMenu;
 if(isAdmin())h+=`<div class="master-block"><button type="button" class="master-toggle" onclick="toggleMasterMenu()">◉ <span>Master</span><em id="masterArrow">⌄</em></button><div id="masterSub" class="master-sub hidden"><a onclick="showUsers()">♟ <span>User Management</span></a><a onclick="showUsers(true)">＋ <span>User Creation</span></a><a onclick="showStations()">▣ <span>Station Entry / Station Name Add</span></a><a onclick="showEquipmentMaster()">▤ <span>Equipment Master</span></a></div></div><a onclick="showBuilder()">＋ <span>New Report Builder</span></a>`;
 h+=`<a onclick="showImporter()">⇩ <span>Import Data</span></a><a onclick="showSettings()">⚙ <span>Theme Setting / Backup</span></a>`;$('nav').innerHTML=h}
 

function toggleMasterMenu(){const sub=$('masterSub');if(!sub)return;const isHidden=sub.classList.contains('hidden');sub.classList.toggle('hidden',!isHidden);const a=$('masterArrow');if(a)a.textContent=isHidden?'⌃':'⌄'}
function showPage(id){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));const page=$(id);if(page)page.classList.add('active')}
function showDashboard(){showPage('dashboard');closeSidebar();renderDashboard()}
function openReport(k){if(!reports[k]||!permsFor(currentUser,k).view){alert('You do not have View permission for this report.');return}if(k===CCR_REPORT_KEY)ccrView='main';current=k;editIndex=null;showPage('report');closeSidebar();$('reportTitle').textContent=reports[k].title;$('reportDesc').textContent='Responsive report • Add / Edit / Delete / Excel / PDF';renderReport()}
function showLocation(){showPage('location');closeSidebar();renderLocation()}
function showImporter(){if(!isAdmin()){alert('Only Admin can import data.');return}showPage('importer');closeSidebar();populateImportTargets()}
function showUsers(form=false){if(!isAdmin())return;closeSidebar();if(form){showPage('userCreation');if($('userCreationForm'))$('userCreationForm').innerHTML='';renderUserForm(null);return}showPage('users');if($('userCreationForm'))$('userCreationForm').innerHTML='';renderUsers()}
function showStations(){if(!isAdmin())return;showPage('stations');closeSidebar();renderStations()}
function renderStations(){const list=state.stations||[];$('stationList').innerHTML=list.length?list.map((n,i)=>`<div class="station-row"><b>${esc(n)}</b><div class="station-actions"><button class="btn" type="button" onclick="editStation(${i})">Edit</button><button class="btn danger" type="button" onclick="deleteStation(${i})">Delete</button></div></div>`).join(''):'<div class="empty">No stations added yet.</div>'}
function addStation(event){event.preventDefault();const input=$('newStationName'),n=input.value.trim();if(!n)return;if((state.stations||[]).some(x=>x.toLowerCase()===n.toLowerCase()))return alert('Station already exists.');state.stations.push(n);save();input.value='';renderStations();renderNav()}
function editStation(i){const old=String((state.stations||[])[i]||'');if(!old)return;const next=prompt('Edit station name?',old);if(next===null)return;const n=next.trim();if(!n)return alert('Station name cannot be empty.');if((state.stations||[]).some((x,idx)=>idx!==i&&x.toLowerCase()===n.toLowerCase()))return alert('Station already exists.');state.stations[i]=n;save();renderStations();renderNav()}
function deleteStation(i){if(!confirm('Delete this station?'))return;state.stations.splice(i,1);save();renderStations();renderNav()}
function showEquipmentMaster(){if(!isAdmin())return;showPage('equipmentMaster');closeSidebar();renderEquipmentMaster()}
function renderEquipmentMaster(){const list=state.equipmentMaster||[];$('equipmentMasterBody').innerHTML=list.length?list.map((x,i)=>`<tr><td>${esc(x.type)}</td><td>${esc(x.name)}</td><td>${esc(x.number||'')}</td><td><button class="btn small-btn" type="button" onclick="editEquipmentMaster(${i})">Edit</button> <button class="btn danger small-btn" type="button" onclick="deleteEquipmentMaster(${i})">Delete</button></td></tr>`).join(''):'<tr><td colspan="4" class="empty">No equipment added yet.</td></tr>'}
function addEquipmentMaster(event){event.preventDefault();const type=$('newEquipmentType').value.trim(),name=$('newEquipmentName').value.trim(),number=$('newEquipmentNumber').value.trim();if(!type||!name||!number)return;if((state.equipmentMaster||[]).some(x=>x.type.toLowerCase()===type.toLowerCase()&&x.name.toLowerCase()===name.toLowerCase()&&String(x.number||'').toLowerCase()===number.toLowerCase()))return alert('Equipment Type, Equipment Name and Equipment Number already exists.');state.equipmentMaster.push({type,name,number});save();$('newEquipmentType').value='';$('newEquipmentName').value='';$('newEquipmentNumber').value='';renderEquipmentMaster();}
function editEquipmentMaster(i){const x=state.equipmentMaster[i];if(!x)return;const form=$('equipmentEditForm');if(!form)return;form.innerHTML=`<h3>Edit Equipment Master</h3><form class="form-grid" onsubmit="saveEquipmentMasterEdit(event,${i})"><div class="field"><label>Equipment Type *</label><input id="editEquipmentType" required value="${attr(x.type||'')}" placeholder="Enter equipment type"></div><div class="field"><label>Equipment Name *</label><input id="editEquipmentName" required value="${attr(x.name||'')}" placeholder="Enter equipment name"></div><div class="field"><label>Equipment Number *</label><input id="editEquipmentNumber" required value="${attr(x.number||'')}" placeholder="Enter equipment number"></div><div class="field full"><div class="modal-actions"><button class="btn gray" type="button" onclick="closeEquipmentEdit()">Cancel</button><button class="btn primary" type="submit">Save Update</button></div></div></form>`;$('equipmentEditModal').classList.remove('hidden');setTimeout(()=>{const el=$('editEquipmentType');if(el){el.focus();el.select()}},0)}
function closeEquipmentEdit(){const m=$('equipmentEditModal');if(m)m.classList.add('hidden')}
function saveEquipmentMasterEdit(event,i){event.preventDefault();const t=$('editEquipmentType').value.trim(),n=$('editEquipmentName').value.trim(),num=$('editEquipmentNumber').value.trim();if(!t||!n||!num)return alert('All three fields are required.');if(state.equipmentMaster.some((e,idx)=>idx!==i&&e.type.toLowerCase()===t.toLowerCase()&&e.name.toLowerCase()===n.toLowerCase()&&String(e.number||'').toLowerCase()===num.toLowerCase()))return alert('Equipment Type, Equipment Name and Equipment Number already exists.');state.equipmentMaster[i]={type:t,name:n,number:num};save();closeEquipmentEdit();renderEquipmentMaster();}
function deleteEquipmentMaster(i){if(!confirm('Delete this equipment master entry?'))return;state.equipmentMaster.splice(i,1);save();renderEquipmentMaster()}
function stationOptions(value){const list=state.stations||[];return `<option value="">Select Station</option>${list.map(x=>`<option value="${attr(x)}" ${String(value??'')===x?'selected':''}>${esc(x)}</option>`).join('')}`}
function showBuilder(){if(!isAdmin())return;showPage('builder');closeSidebar();renderBuilder()}
function showSettings(){showPage('settings');closeSidebar();setHeader()}
function renderDashboard(){const vals=[['⚠ Failure Today',0,'red'],['✓ Resolved Today',0,'green'],['◷ Pending Today',0,'orange'],['◇ Damage Case Till Now',0,'blue'],['⌕ Inspection Stations Today',0,'cyan'],['▣ Available DR Roll',0,'indigo'],['▤ Available Wax Roll',0,'teal'],['▤ Available Receipt Roll',0,'purple'],['▧ Today TVM Roll Issue',0,'teal'],['▧ Today Wax Roll Issue',0,'red'],['▧ Today Receipt Roll Issue',0,'darkteal'],['▧ Today TVM Roll Issue',0,'blue']];$('cards').innerHTML=vals.map(v=>`<div class="card ${v[2]}"><b>${v[0]}</b><strong>0</strong><small>Tap to view details →</small></div>`).join('');$('activities').innerHTML='<p>🟢 Portal ready - no activity yet</p>'}
function summaryRows(){const rows=[];Object.keys(reports).filter(k=>k!=='summary'&&k!=='location').forEach(k=>(state.records[k]||[]).forEach((x,idx)=>{const isFail=k==='failure';rows.push({...x,'Date':x.Date||x.date||new Date(x._savedAt||Date.now()).toLocaleDateString(),'Date & Time':x['Date & Time']|| (x._savedAt?new Date(x._savedAt).toLocaleString():''),'Agent':x.Agent||x.agent||x._userName||'','Employee ID / User Name':x._userId||'','Latitude':x._lat??'','Longitude':x._lng??'','Map URL':x._map||'','Entry Photo':x._photo||'','Failure Count':isFail?1:'','L1 Faulty':isFail&&/fault|fail|yes|1/i.test(String(x.L1||''))?1:'','PCR Faulty':isFail&&/fault|fail|yes|1/i.test(String(x.PCR||''))?1:'','D1 Faulty':isFail&&/fault|fail|yes|1/i.test(String(x.D1||''))?1:'','Material Quantity':x.Quantity||x['Added Quantity']||'','Inventory Closing':x.Closing||'','Remarks':x.Remarks||'',_source:k,_sourceIndex:idx});}));return rows}
function summaryFieldList(rows){const base=['Date','Date & Time','Agent','Employee ID / User Name','Station','Product Name','Serial Number','Part / Product Photo','Latitude','Longitude','Map URL','Entry Photo','Failure Count','L1 Faulty','PCR Faulty','D1 Faulty','Material Quantity','Inventory Closing','Remarks'];const seen=new Set(base);rows.forEach(x=>Object.keys(x).forEach(k=>{if(!k.startsWith('_')&&!seen.has(k)){seen.add(k);base.push(k)}}));return base}
function renderReport(){if(current===CCR_REPORT_KEY){renderCCRReport();return}const r=reports[current],p=permsFor(currentUser,current);let displayRows=current==='summary'?summaryRows():(state.records[current]||[]);if(current==='summary')r.fields=summaryFieldList(displayRows);let buttons='';if(p.add&&current!=='summary')buttons+=`<button class="btn primary" onclick="addRecord()">＋ Add</button>`;buttons+=`<button class="btn gray" onclick="exportExcel('${current}')">Excel</button><button class="btn gray" onclick="exportPDF('${current}')">PDF</button>`;if(isAdmin())buttons+=`<button class="btn gray" onclick="$('importFile').click()">Import Excel/CSV</button><input id="importFile" type="file" accept=".csv,.xlsx,.xls" hidden onchange="importIntoCurrent(event)">`;$('reportActions').innerHTML=buttons;$('reportTitle').textContent=r.title;$('reportDesc').textContent=current==='summary'?'Auto populated from report and agent entries. Use Edit to correct the original entry.':'Responsive report • Add / Edit / Delete / Excel / PDF';if(current==='summary'){$('reportForm').innerHTML=`<div class="summary-filters panel"><div class="form-grid"><div class="field"><label>From Date</label><input id="sumFrom" type="date" onchange="applySummaryFilter()"></div><div class="field"><label>To Date</label><input id="sumTo" type="date" onchange="applySummaryFilter()"></div><div class="field"><label>Agent</label><select id="sumAgent" onchange="applySummaryFilter()"><option value="">All Agents</option>${[...new Set(displayRows.map(x=>x.Agent).filter(Boolean))].sort().map(a=>`<option>${esc(a)}</option>`).join('')}</select></div><div class="field"><label>Report</label><select id="sumReport" onchange="applySummaryFilter()"><option value="">All Reports</option>${[...new Set(displayRows.map(x=>x._source).filter(Boolean))].map(k=>`<option value="${attr(k)}">${esc(roleLabel(k))}</option>`).join('')}</select></div><div class="field full"><div class="actions"><button class="btn gray" type="button" onclick="resetSummaryFilter()">Reset Filter</button><span id="summaryCount" class="user-count">0 entries</span></div></div></div></div>`;}else renderRecordForm({});$('thead').innerHTML='<tr>'+r.fields.map(f=>`<th>${esc(f)}</th>`).join('')+'<th>Actions</th></tr>';renderReportRows(displayRows)}
function renderReportRows(rows){const r=reports[current],p=permsFor(currentUser,current);$('tbody').innerHTML=rows.map((row,i)=>`<tr>${r.fields.map(f=>{const v=row[f]??'';if(f==='Map URL'&&v)return `<td><a href="${attr(v)}" target="_blank" rel="noopener">Open Map</a></td>`;if(f==='Entry Photo'&&v)return `<td><img class="user-thumb" src="${attr(v)}"></td>`;return `<td>${esc(v)}</td>`}).join('')}<td>${current==='summary'?`<button class="btn gray small-btn" onclick="editSummaryRecord(${i})">Edit</button>`:`${p.edit?`<button class="btn gray small-btn" onclick="editRecord(${i})">Edit</button>`:''} ${p.delete?`<button class="btn danger small-btn" onclick="deleteRecord(${i})">Delete</button>`:''}`}</td></tr>`).join('')||`<tr><td colspan="${r.fields.length+1}" class="empty">No records yet.</td></tr>`;if(current==='summary'&&$('summaryCount'))$('summaryCount').textContent=`${rows.length} entries`}
function editSummaryRecord(i){const row=summaryRows()[i];if(!row||!row._source)return;const k=row._source;if(!permsFor(currentUser,k).edit){alert('Edit permission is not granted for this report.');return}current=k;editIndex=row._sourceIndex;showPage('report');closeSidebar();renderReport()}
function applySummaryFilter(){let rows=summaryRows();const from=$('sumFrom')?.value,to=$('sumTo')?.value,agent=$('sumAgent')?.value,rep=$('sumReport')?.value;rows=rows.filter(x=>{const raw=String(x['Date & Time']||x.Date||'');const d=raw.slice(0,10);return (!from||d>=from)&&(!to||d<=to)&&(!agent||x.Agent===agent)&&(!rep||x._source===rep)});renderReportRows(rows)}
function resetSummaryFilter(){['sumFrom','sumTo'].forEach(id=>{if($(id))$(id).value=''});if($('sumAgent'))$('sumAgent').value='';if($('sumReport'))$('sumReport').value='';renderReportRows(summaryRows())}
function addRecord(){if(current==='summary'){alert('Final Summary is generated automatically from report entries.');return}if(!permsFor(currentUser,current).add){alert('Add permission is not granted.');return}editIndex=null;renderRecordForm({})}
function openNativePicker(btn){const input=btn.previousElementSibling;if(!input)return;try{if(typeof input.showPicker==='function')input.showPicker();else input.focus()}catch(e){input.focus()}}
function uniqueValues(field){const vals=new Set();Object.values(state.records||{}).forEach(rows=>(rows||[]).forEach(x=>{const v=String(x?.[field]??'').trim();if(v)vals.add(v)}));return [...vals].sort((a,b)=>a.localeCompare(b));}
function stationEquipmentTypeOptions(v){const vals=[...new Set((state.equipmentMaster||[]).map(x=>x.type).filter(Boolean))];const cur=String(v??'');if(cur&&!vals.includes(cur))vals.unshift(cur);return `<option value="">Select Equipment Type</option>${vals.map(x=>`<option value="${attr(x)}" ${x===cur?'selected':''}>${esc(x)}</option>`).join('')}`}
function stationEquipmentNameOptions(v,type){const vals=(state.equipmentMaster||[]).filter(x=>!type||x.type===type).map(x=>x.name).filter(Boolean);const cur=String(v??'');if(cur&&!vals.includes(cur))vals.unshift(cur);return `<option value="">Select Equipment Name</option>${[...new Set(vals)].map(x=>`<option value="${attr(x)}" ${x===cur?'selected':''}>${esc(x)}</option>`).join('')}`}
function stationEquipmentNumberOptions(v,type,name){const vals=(state.equipmentMaster||[]).filter(x=>(!type||x.type===type)&&(!name||x.name===name)).map(x=>x.number).filter(Boolean);const cur=String(v??'');if(cur&&!vals.includes(cur))vals.unshift(cur);return `<option value="">Select Equipment Number</option>${[...new Set(vals)].map(x=>`<option value="${attr(x)}" ${x===cur?'selected':''}>${esc(x)}</option>`).join('')}`}
function updateStationEquipmentNames(){const type=$('stationEquipmentType')?.value||'';const sel=$('stationEquipmentName');if(sel)sel.innerHTML=stationEquipmentNameOptions(sel.value,type);updateStationEquipmentNumbers()}
function updateStationEquipmentNumbers(){const type=$('stationEquipmentType')?.value||'';const name=$('stationEquipmentName')?.value||'';const sel=$('stationEquipmentNumber');if(sel)sel.innerHTML=stationEquipmentNumberOptions(sel.value,type,name)}
function stationSelect(name,label,v,opts){return `<div class="field"><label>${esc(label)}</label><select name="${attr(name)}" required>${opts}</select></div>`}
function fieldInput(f,v){const raw=String(f).trim(),key=raw.toLowerCase(),safe=attr(v??'');if(key==='station name'||key==='station'){return `<div class="field"><label>${esc(f)}</label><select name="${attr(f)}" required>${stationOptions(v)}</select></div>`}if(key==='equipment type'){return `<div class="field"><label>${esc(f)}</label><select id="stationEquipmentType" name="${attr(f)}" required onchange="updateStationEquipmentNames()">${stationEquipmentTypeOptions(v)}</select></div>`}if(key==='equipment name'){return `<div class="field"><label>${esc(f)}</label><select id="stationEquipmentName" name="${attr(f)}" required onchange="updateStationEquipmentNumbers()">${stationEquipmentNameOptions(v,$('stationEquipmentType')?.value||'')}</select></div>`}if(key==='equipment number'){return `<div class="field"><label>${esc(f)}</label><select id="stationEquipmentNumber" name="${attr(f)}" required>${stationEquipmentNumberOptions(v,$('stationEquipmentType')?.value||'', $('stationEquipmentName')?.value||'')}</select></div>`}if(key==='equipment serial number'){return `<div class="field"><label>${esc(f)}</label><input type="text" name="${attr(f)}" value="${safe}" required placeholder="Enter Equipment Serial Number"></div>`}if(key==='g7 status'){return stationSelect(f,f,v,`<option value="">Select G7 Status</option><option value="OK" ${String(v)==='OK'?'selected':''}>OK</option><option value="Faulty" ${String(v)==='Faulty'?'selected':''}>Faulty</option>`)}if(key==='transaction file pending'){return stationSelect(f,f,v,`<option value="">Select Yes or No</option><option value="Yes" ${String(v)==='Yes'?'selected':''}>Yes</option><option value="No" ${String(v)==='No'?'selected':''}>No</option>`)}if(key==='equipment photo'){return `<div class="field full"><label>${esc(f)}</label><div class="photo-actions"><input id="stationEquipmentGallery" type="file" accept="image/*" hidden onchange="readStationEquipmentPhoto(event)"><input id="stationEquipmentCamera" type="file" accept="image/*" capture="environment" hidden onchange="readStationEquipmentPhoto(event)"><button type="button" class="btn gray" onclick="$('stationEquipmentGallery').click()">🖼️ Gallery / Browse</button><button type="button" class="btn primary" onclick="openCamera('stationEquipment')">📷 Camera</button></div><input id="stationEquipmentPhoto" name="${attr(f)}" type="hidden" value="${safe}"><div id="stationEquipmentPhotoPreview" class="photo-preview">${v?`<img src="${safe}" alt="Equipment">`:'No photo selected'}</div></div>`}if(key==='date'){return `<div class="field date-field"><label>${esc(f)}</label><div class="date-control"><input type="date" name="${attr(f)}" value="${safe}" aria-label="Select ${esc(f)}"><button type="button" class="calendar-btn" onclick="openNativePicker(this)">📅 Select Date</button></div></div>`}if(key==='date & time'||key==='datetime'||key==='date time'){return `<div class="field date-field"><label>${esc(f)}</label><div class="date-control"><input type="datetime-local" name="${attr(f)}" value="${safe}" aria-label="Select ${esc(f)}"><button type="button" class="calendar-btn" onclick="openNativePicker(this)">📅 Select Date & Time</button></div></div>`}if(key==='time'){return `<div class="field date-field"><label>${esc(f)}</label><div class="date-control"><input type="time" name="${attr(f)}" value="${safe}" aria-label="Select ${esc(f)}"><button type="button" class="calendar-btn" onclick="openNativePicker(this)">⏰ Select Time</button></div></div>`}return `<div class="field"><label>${esc(f)}</label><input type="text" name="${attr(f)}" value="${safe}" placeholder="Enter ${attr(f)}"></div>`}
function readEntryPhoto(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{$('entryPhoto').value=r.result;$('entryPhotoPreview').innerHTML=`<img src="${r.result}" alt="Entry">`;$('ocrStatus').textContent='Photo ready. Reading serial…';setTimeout(runSerialOCR,100)};r.readAsDataURL(f)}
function readStationEquipmentPhoto(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const val=r.result;$('stationEquipmentPhoto').value=val;$('stationEquipmentPhotoPreview').innerHTML=`<img src="${val}" alt="Equipment">`};r.readAsDataURL(f)}
function renderRecordForm(obj){const r=reports[current];if(current==='station'){$('reportForm').innerHTML=`<form class="form-grid" onsubmit="submitRecord(event)">${r.fields.map(f=>fieldInput(f,obj[f])).join('')}<div class="field full"><div class="actions"><button class="btn primary">${editIndex===null?'Save':'Update'}</button><button type="button" class="btn gray" onclick="$('reportForm').innerHTML=''">Cancel</button></div></div></form>`;updateStationEquipmentNames();return}$('reportForm').innerHTML=`<form class="form-grid" onsubmit="submitRecord(event)"><div class="field"><label>Product Name</label><input name="Product Name" value="${attr(obj['Product Name']??'')}" placeholder="Enter Product Name"></div><div class="field"><label>Serial Number</label><input id="serialField" name="Serial Number" value="${attr(obj['Serial Number']??'')}" placeholder="Enter or scan Serial Number"></div><div class="field full"><label>Part / Product Photo</label><div class="photo-actions"><input id="entryGallery" type="file" accept="image/*" hidden onchange="readEntryPhoto(event)"><input id="entryCamera" type="file" accept="image/*" capture="environment" hidden onchange="readEntryPhoto(event)"><button type="button" class="btn gray" onclick="$('entryGallery').click()">🖼️ Gallery</button><button type="button" class="btn primary" onclick="openCamera('entry')">📷 Camera</button><button type="button" class="btn gray" onclick="runSerialOCR()">🔎 Read Serial from Photo</button></div><input id="entryPhoto" type="hidden" value="${attr(obj._photo||'')}"><div id="ocrStatus" class="muted"></div><div id="entryPhotoPreview" class="photo-preview">${obj._photo?`<img src="${attr(obj._photo)}" alt="Entry">`:'No photo selected'}</div></div>${r.fields.filter(f=>!['Product Name','Serial Number','Part / Product Photo','Entry Photo'].includes(f)).map(f=>fieldInput(f,obj[f])).join('')}<div class="field full"><div class="actions"><button class="btn primary">${editIndex===null?'Save':'Update'}</button><button type="button" class="btn gray" onclick="$('reportForm').innerHTML=''">Cancel</button></div></div></form>`}
function submitRecord(e){e.preventDefault();const p=permsFor(currentUser,current);if(editIndex===null&&!p.add)return;if(editIndex!==null&&!p.edit)return;const d=Object.fromEntries(new FormData(e.target).entries());if(current==='station'){const photo=$('stationEquipmentPhoto')?.value||'';d['Equipment Photo']=photo;d._photo=photo}else{d._photo=$('entryPhoto')?.value||'';d['Part / Product Photo']=d._photo;d['Entry Photo']=d._photo}d['Agent']=d['Agent']||currentUser.name;d['Employee ID / User Name']=d['Employee ID / User Name']||currentUser.id;d._userId=currentUser.id;d._userName=currentUser.name;d._savedAt=new Date().toISOString();if(current==='summary'){} if(editIndex===null)state.records[current].push(d);else state.records[current][editIndex]=d;state.activities.push(`${reports[current].title} ${editIndex===null?'added':'updated'} by ${currentUser.name}`);captureLocation(d);save();$('reportForm').innerHTML='';renderReport();renderDashboard()}
function editRecord(i){if(current==='summary'){alert('Final Summary is generated automatically from report entries.');return}if(!permsFor(currentUser,current).edit){alert('Edit permission is not granted.');return}editIndex=i;renderRecordForm(state.records[current][i])}
function deleteRecord(i){if(current==='summary'){alert('Final Summary is generated automatically from report entries.');return}if(!permsFor(currentUser,current).delete){alert('Delete permission is not granted.');return}if(!confirm('Delete this record?'))return;state.records[current].splice(i,1);state.activities.push(`${reports[current].title} record deleted by ${currentUser.name}`);save();renderReport();renderDashboard()}
async function reverseLocationName(lat,lng){try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(lat)}&lon=${encodeURIComponent(lng)}&zoom=18&addressdetails=1`,{headers:{'Accept':'application/json'}});if(!r.ok)return 'Live GPS Location';const j=await r.json();return j.display_name||'Live GPS Location'}catch(e){return 'Live GPS Location'}}
function captureLocation(data){if(!navigator.geolocation)return;navigator.geolocation.getCurrentPosition(async pos=>{const now=new Date().toISOString();const lat=pos.coords.latitude,lng=pos.coords.longitude;const loc={employeeCode:currentUser.employeeCode||currentUser.code||currentUser.id||'',employeeId:currentUser.id||'',datetime:now,lat,lng,map:`https://www.google.com/maps?q=${lat},${lng}`,locationName:'Live GPS Location'};state.locations.push(loc);const locIndex=state.locations.length-1;const name=await reverseLocationName(lat,lng);if(state.locations[locIndex])state.locations[locIndex].locationName=name;const recs=state.records[current]||[];const target=recs[editIndex===null?recs.length-1:editIndex];if(target){target._lat=lat;target._lng=lng;target._map=loc.map;target._locationName=name;target._locationTime=now}save();renderLocation();if(current==='summary')renderReport()},()=>{}, {enableHighAccuracy:true,timeout:10000,maximumAge:0});}
function renderLocation(){const b=$('locationBody');b.innerHTML=state.locations.map(x=>`<tr><td>${esc(x.employeeCode||x.userId||'')}</td><td>${esc(x.employeeId||x.userId||'')}</td><td>${esc(new Date(x.datetime).toLocaleString())}</td><td>${Number(x.lat).toFixed(6)}</td><td>${Number(x.lng).toFixed(6)}</td><td><a href="${attr(x.map)}" target="_blank" rel="noopener">Open Google Map</a></td><td>${esc(x.locationName||'Live GPS Location')}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No live GPS entries yet. Add a report entry from the APK and allow location access.</td></tr>'} 

function deleteLocation(i){if(!isAdmin())return;if(!confirm('Delete location entry?'))return;state.locations.splice(i,1);save();renderLocation()}
function exportLocationExcel(){downloadWorkbook([{name:'Agent Location History',rows:state.locations.map(x=>({'Employee Code':x.employeeCode||x.userId||'','Employee ID':x.employeeId||x.userId||'','Date & Time':new Date(x.datetime).toLocaleString(),Latitude:x.lat,Longitude:x.lng,'Google Maps Live URL':x.map,'Location Name':x.locationName||'Live GPS Location'}))}], 'Agent_Location_History.xlsx')}
function printLocation(){const headers=['Employee Code','Employee ID','Date & Time','Latitude','Longitude','Google Maps Live URL','Location Name'];const rows=state.locations.map(x=>headers.map(h=>({'Employee Code':x.employeeCode||x.userId||'','Employee ID':x.employeeId||x.userId||'','Date & Time':new Date(x.datetime).toLocaleString(),Latitude:x.lat,Longitude:x.lng,'Google Maps Live URL':x.map,'Location Name':x.locationName||'Live GPS Location'}[h])));printTable('Agent Location History',headers,rows)}
function exportExcel(k){const rows=k==='summary'?summaryRows():(k===CCR_REPORT_KEY?ccrViewRows(ccrVisibleRows()):(state.records[k]||[]));downloadWorkbook([{name:reports[k].title.slice(0,31),rows}],`${reports[k].title.replace(/[^a-z0-9]+/gi,'_')}.xlsx`)}
function exportPDF(k){const r=reports[k];const rows=k===CCR_REPORT_KEY?ccrViewRows(ccrVisibleRows()):(state.records[k]||[]);printTable(r.title,r.fields,rows.map(x=>r.fields.map(f=>x[f]??'')))}
function printTable(title,heads,rows){const w=window.open('','_blank');if(!w){alert('Please allow popups for PDF print.');return}w.document.write(`<html><head><title>${esc(title)}</title><style>body{font-family:Arial;padding:20px}h2{margin-bottom:15px}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #bbb;padding:6px;text-align:left}th{background:#eee}@media print{button{display:none}}</style></head><body><h2>${esc(title)}</h2><table><thead><tr>${heads.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function downloadWorkbook(sheets,filename){if(window.XLSX){const wb=XLSX.utils.book_new();sheets.forEach(s=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(s.rows),s.name));XLSX.writeFile(wb,filename);return}let html='<table><tr>'+Object.keys(sheets[0].rows[0]||{}).map(x=>`<th>${esc(x)}</th>`).join('')+'</tr>';(sheets[0].rows||[]).forEach(r=>html+=`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`);html+='</table>';download(filename.replace('.xlsx','.xls'),html,'application/vnd.ms-excel')}
function download(name,data,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function normalizeRows(rows,k){const fields=reports[k].fields;return rows.map(raw=>{const out={};fields.forEach(f=>{const hit=Object.keys(raw).find(h=>h.trim().toLowerCase()===f.toLowerCase());out[f]=hit?raw[hit]:''});return out})}
function parseFile(file,cb){if(!file)return;const ext=file.name.toLowerCase().split('.').pop();const r=new FileReader();r.onload=e=>{try{if((ext==='xlsx'||ext==='xls')&&window.XLSX){const wb=XLSX.read(e.target.result,{type:'array'});const all=[];wb.SheetNames.forEach(sn=>{const ws=wb.Sheets[sn];XLSX.utils.sheet_to_json(ws,{defval:''}).forEach(x=>{if(!Object.keys(x).some(k=>/^(role|report|report name|role\/report)$/i.test(k)))x.Role=sn;all.push(x)})});cb(all);}else{cb(csvToRows(new TextDecoder().decode(e.target.result)))} }catch(err){alert('Could not read file: '+err.message)}};r.readAsArrayBuffer(file)}
function csvToRows(txt){const lines=txt.split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return[];const parse=s=>{let a=[],c='',q=false;for(let i=0;i<s.length;i++){const ch=s[i];if(ch==='"'&&s[i+1]==='"'){c+='"';i++;continue}if(ch==='"'){q=!q;continue}if(ch===','&&!q){a.push(c);c='';continue}c+=ch}a.push(c);return a};const h=parse(lines[0]);return lines.slice(1).map(l=>{const v=parse(l),o={};h.forEach((x,i)=>o[x.trim()]=v[i]||'');return o})}
function populateImportTargets(){const sel=$('importTarget');if(sel)sel.innerHTML='<option value="">Auto detect all reports from workbook</option>'+Object.keys(reports).filter(k=>k!=='summary').map(k=>`<option value="${k}">${esc(reports[k].title)}</option>`).join('')}
function importRowsAuto(rows,forced){const imported=[];rows.forEach(raw=>{const keys=Object.keys(raw);let target=forced;const roleKey=keys.find(k=>/^(role|report|report name|role\/report)$/i.test(k));if(!target&&roleKey){const rv=String(raw[roleKey]||'').trim().toLowerCase();target=Object.keys(reports).find(k=>k.toLowerCase()===rv||roleLabel(k).toLowerCase()===rv)}if(!target){let best={k:null,score:0};Object.keys(reports).filter(k=>k!=='summary').forEach(k=>{const fs=reports[k].fields.map(x=>x.toLowerCase());const score=keys.reduce((n,h)=>n+(fs.includes(h.trim().toLowerCase())?1:0),0);if(score>best.score)best={k,score}});target=best.k}if(target&&reports[target]){const out=normalizeRows([raw],target)[0];out._importedAt=new Date().toISOString();imported.push([target,out])}});return imported}
function runImport(){const f=$('importFileMain').files[0];if(!f)return alert('Select a file.');const forced=$('importTarget').value||null;parseFile(f,rows=>{const pairs=importRowsAuto(rows,forced);pairs.forEach(([k,row])=>{state.records[k] ||= [];state.records[k].push(row)});state.activities.push(`Imported ${pairs.length} rows with automatic report/role mapping`);save();$('importStatus').textContent=`Imported ${pairs.length} rows. Existing records were preserved. Columns were mapped by headers.`;renderDashboard()})}
function importIntoCurrent(e){const f=e.target.files[0];if(!f)return;parseFile(f,rows=>{const n=normalizeRows(rows,current);state.records[current].push(...n);save();renderReport();alert(`Imported ${n.length} rows.`)})}
function downloadImportTemplate(){const sheets=Object.keys(reports).filter(k=>k!=='summary').map(k=>({name:reports[k].title.slice(0,31),rows:[{Role:reports[k].title,...Object.fromEntries(reports[k].fields.map(f=>[f,'']))}]}));downloadWorkbook(sheets,'NMRC Inventory_All_Roles_Import_Template.xlsx')}
function exportAllData(){const sheets=Object.keys(reports).map(k=>({name:reports[k].title.slice(0,31),rows:state.records[k]}));sheets.push({name:'Agent Location History',rows:state.locations});sheets.push({name:'Users',rows:state.users.map(u=>({...u,password:undefined}))});downloadWorkbook(sheets,'NMRC Inventory_All_Data.xlsx')}
function createDynamicReport(){const name=prompt('New report name?');if(!name?.trim())return;const raw=prompt('Fields separated by comma?','Date,Agent,Station,Serial Number,Remarks');if(!raw)return;const fields=raw.split(',').map(x=>x.trim()).filter(Boolean);if(!fields.length)return;const k='dynamic_'+Date.now();reports[k]={title:name.trim(),fields};state.records[k]=[];state.dynamic.push(k);state.reportDefs[k]=reports[k];save();renderNav();renderBuilder();openReport(k)}
function renderBuilder(){const d=$('builderList');d.innerHTML=(state.dynamic||[]).map(k=>`<div class="panel" style="margin-top:14px"><h3>${esc(reports[k].title)}</h3><p>${reports[k].fields.map(esc).join(' • ')}</p><div class="actions"><button class="btn primary" onclick="openReport('${k}')">Open Report</button><button class="btn danger" onclick="deleteDynamic('${k}')">Delete Report</button></div></div>`).join('')||'<div class="panel" style="margin-top:14px"><div class="empty">No custom reports created yet.</div></div>'}
function deleteDynamic(k){if(!isAdmin()||!confirm('Delete this custom report and its records?'))return;delete reports[k];delete state.records[k];state.dynamic=state.dynamic.filter(x=>x!==k);delete state.reportDefs[k];save();renderNav();renderBuilder()}
function normalizeUser(u){u.roles ||= [];u.permissions ||= {};applyCCRRolePermissions(u);return u}
function renderUsers(){if(!isAdmin())return;const body=$('userBody');$('userCount').textContent=`Total Users: ${state.users.length}`;body.innerHTML=state.users.map((u,i)=>{const roles=u.roles?.length?u.roles:[];const roleText=[roles.length===STATIC_ROLES.length?'All Roles':roles.map(roleLabel).join(', ')||'None',u.ccrRole?`CCR: ${u.ccrRole}`:''].filter(Boolean).join(' • ');const p=roles.map(k=>`${roleLabel(k)} A:${u.permissions?.[k]?.add?'✓':'×'} E:${u.permissions?.[k]?.edit?'✓':'×'} D:${u.permissions?.[k]?.delete?'✓':'×'}`).join('<br>');return `<tr><td>${u.photo?`<img class="user-thumb" src="${attr(u.photo)}">`:'—'}</td><td>${esc(u.name)}</td><td>${esc(u.id)}</td><td>${esc(u.mobile)}</td><td>${esc(roleText)}</td><td>${u.lastLogin?esc(new Date(u.lastLogin).toLocaleString()):'Never'}</td><td class="permission-cell">${p||'No report access'}</td><td><button class="btn primary small-btn" onclick="editUser(${i})">Edit</button> <button class="btn danger small-btn" onclick="deleteUser(${i})">Delete</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No users created yet.</td></tr>'}
function renderUserForm(index){if(!isAdmin())return;userEditIndex=index;const u=index===null?{name:'',id:'',password:'',mobile:'',photo:'',roles:[],permissions:{},ccrRoles:[],ccrPermissions:{}}:state.users[index];const roleKeys=[...STATIC_ROLES.map(x=>x[0]),...state.dynamic];const all=roleKeys.length>0&&roleKeys.every(k=>u.roles?.includes(k));$('userCreationForm').innerHTML=`<div class="panel user-create"><div class="form-head"><div><h3>${index===null?'User Creation':'Edit User'}</h3><div class="muted">Admin assigns one role, multiple roles, or Select All Roles. Permissions are per report.</div></div><span class="admin-badge">ADMIN ONLY</span></div><form class="form-grid" onsubmit="saveUser(event)"><div class="field"><label>Employee Name *</label><input name="name" required value="${attr(u.name)}"></div><div class="field"><label>Employee ID *</label><input name="id" required value="${attr(u.id)}" ${index!==null?'readonly':''}></div><div class="field"><label>Employee Password *</label><input name="password" type="password" required value="${attr(u.password||'')}"></div><div class="field"><label>Employee Mobile Number *</label><input name="mobile" required value="${attr(u.mobile)}"></div><div class="field"><label>Employee Photo (Admin only)</label><div class="photo-actions"><input id="employeeGallery" type="file" accept="image/*" hidden onchange="previewEmployeePhoto(event)"><input id="employeeCamera" type="file" accept="image/*" capture="user" hidden onchange="previewEmployeePhoto(event)"><button type="button" class="btn gray" onclick="$('employeeGallery').click()">🖼️ Gallery</button><button type="button" class="btn primary" onclick="openCamera('employee')">📷 Camera</button></div><input id="employeePhotoData" type="hidden" value="${attr(u.photo||'')}"><div id="employeePhotoPreview" class="photo-preview">${u.photo?`<img src="${attr(u.photo)}">`:'No photo selected'}</div></div><div class="field full"><label>CCR Roles</label><select id="ccrRoleSelector" multiple size="5">${CCR_ROLE_OPTIONS.map(r=>`<option value="${attr(r)}" ${getCCRRoles(u).includes(r)?'selected':''}>${esc(r)}</option>`).join('')}</select><div class="muted">Admin can assign any one or multiple CCR roles. Actual report permissions are controlled below by Admin.</div><div class="role-permission-list"><div class="role-permission-row five"><b>CCR Report</b><b>View</b><b>Add</b><b>Edit</b><b>Delete</b></div>${Object.entries({management:'CCR Management',received:'Complaint Received',status:'Complaint Reply / Pending Status',final:'Final Summary'}).map(([k,n])=>{const pr=u.ccrPermissions?.[k]||{};return `<div class="role-permission-row five"><b>${n}</b><label><input class="ccr-perm-view" data-ccr-report="${k}" type="checkbox" ${pr.view?'checked':''}> View</label><label><input class="ccr-perm-add" data-ccr-report="${k}" type="checkbox" ${pr.add?'checked':''}> Add</label><label><input class="ccr-perm-edit" data-ccr-report="${k}" type="checkbox" ${pr.edit?'checked':''}> Edit</label><label><input class="ccr-perm-delete" data-ccr-report="${k}" type="checkbox" ${pr.delete?'checked':''}> Delete</label></div>`}).join('')}</div></div><div class="field full"><label>Role Selection</label><select id="roleSelector" onchange="roleSelectorChanged(this)"><option value="__all__">Select All Roles</option><option value="__none__">Clear Role Selection</option>${roleKeys.map(k=>`<option value="${attr(k)}">${esc(roleLabel(k))}</option>`).join('')}</select><label class="check-row role-all"><input id="allRoles" type="checkbox" ${all?'checked':''} onchange="toggleAllRoles(this)"><b>Select All Roles</b><span class="muted">Select every report / role at once</span></label><div class="role-permission-list"><div class="role-permission-row"><b>Report / Role</b><b>View</b><b>Add</b><b>Edit</b><b>Delete</b></div>${roleKeys.map(k=>{const pr=u.permissions?.[k]||{};return `<div class="role-permission-row five"><label class="role-check"><input class="role-access" data-role="${attr(k)}" type="checkbox" ${u.roles?.includes(k)?'checked':''}> <b>${esc(roleLabel(k))}</b></label><label><input class="perm-view" data-role="${attr(k)}" type="checkbox" ${u.roles?.includes(k)?'checked':''}> View</label><label><input class="perm-add" data-role="${attr(k)}" type="checkbox" ${pr.add?'checked':''}> Add</label><label><input class="perm-edit" data-role="${attr(k)}" type="checkbox" ${pr.edit?'checked':''}> Edit</label><label><input class="perm-delete" data-role="${attr(k)}" type="checkbox" ${pr.delete?'checked':''}> Delete</label></div>`}).join('')}</div></div><div class="field full"><div class="actions"><button class="btn primary">${index===null?'＋ Create User':'✓ Update User'}</button><button type="button" class="btn gray" onclick="cancelUserForm()">Cancel</button></div></div></form></div>`;$('userCreationForm').scrollIntoView({behavior:'smooth',block:'start'})}
function roleSelectorChanged(sel){if(sel.value==='__all__'){const cb=$('allRoles');if(cb){cb.checked=true;toggleAllRoles(cb)}}else if(sel.value==='__none__'){document.querySelectorAll('.role-access,.perm-view').forEach(x=>x.checked=false);if($('allRoles'))$('allRoles').checked=false}else{const k=sel.value;const ra=document.querySelector(`.role-access[data-role="${CSS.escape(k)}"]`);const pv=document.querySelector(`.perm-view[data-role="${CSS.escape(k)}"]`);if(ra)ra.checked=true;if(pv)pv.checked=true;if($('allRoles'))$('allRoles').checked=false}}
function toggleAllRoles(cb){document.querySelectorAll('.role-access,.perm-view').forEach(x=>x.checked=cb.checked)}
function previewEmployeePhoto(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{$('employeePhotoData').value=r.result;$('employeePhotoPreview').innerHTML=`<img src="${r.result}">`};r.readAsDataURL(f)}
function saveUser(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());const roleKeys=[...STATIC_ROLES.map(x=>x[0]),...state.dynamic];const roles=[...document.querySelectorAll('.role-access:checked')].map(x=>x.dataset.role);if(!roles.length)return alert('Select at least one role or Select All Roles.');const permissions={};roleKeys.forEach(k=>permissions[k]={view:$(`.perm-view[data-role="${CSS.escape(k)}"]`)?.checked||false,add:$(`.perm-add[data-role="${CSS.escape(k)}"]`)?.checked||false,edit:$(`.perm-edit[data-role="${CSS.escape(k)}"]`)?.checked||false,delete:$(`.perm-delete[data-role="${CSS.escape(k)}"]`)?.checked||false});const ccrRoles=[...document.querySelectorAll('#ccrRoleSelector option:checked')].map(x=>x.value).filter(Boolean);const ccrPermissions={};Object.keys(CCR_REPORT_KEYS).forEach(k=>ccrPermissions[k]={view:$(`.ccr-perm-view[data-ccr-report="${k}"]`)?.checked||false,add:$(`.ccr-perm-add[data-ccr-report="${k}"]`)?.checked||false,edit:$(`.ccr-perm-edit[data-ccr-report="${k}"]`)?.checked||false,delete:$(`.ccr-perm-delete[data-ccr-report="${k}"]`)?.checked||false});const u={name:d.name.trim(),id:d.id.trim(),password:d.password,mobile:d.mobile.trim(),photo:$('employeePhotoData').value,roles,allRoles:$('allRoles')?.checked||false,permissions,ccrRoles,ccrRole:ccrRoles[0]||'',ccrPermissions,lastLogin:userEditIndex===null?'':(state.users[userEditIndex]?.lastLogin||'')};if(userEditIndex===null){if(state.users.some(x=>x.id.toLowerCase()===u.id.toLowerCase()))return alert('Employee ID already exists.');state.users.push(u);state.activities.push(`New employee ${u.name} created`)}else{state.users[userEditIndex]=u;state.activities.push(`Employee ${u.name} updated`)}save();userEditIndex=null;if($('userForm'))$('userCreationForm').innerHTML='';renderNav();showUsers(false);renderDashboard()}
function cancelUserForm(){userEditIndex=null;$('userCreationForm').innerHTML=''}
function editUser(i){if(!isAdmin())return;showPage('userCreation');if($('userCreationForm'))$('userCreationForm').innerHTML='';renderUserForm(i)}
function deleteUser(i){if(!confirm('Delete this employee?'))return;state.users.splice(i,1);save();renderUsers();renderNav()}
function downloadBackup(){download('aurionpro_backup.json',JSON.stringify(state,null,2),'application/json')}
function restoreBackup(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state=JSON.parse(r.result);Object.keys(BASE_REPORTS).forEach(k=>state.records[k] ||= []);state.reportDefs ||= {};reports=deepClone(BASE_REPORTS);(state.dynamic||[]).forEach(k=>{if(state.reportDefs[k])reports[k]=state.reportDefs[k]});save();renderNav();renderDashboard();alert('Backup restored.')}catch(err){alert('Invalid backup file.')}};r.readAsText(f)}
document.addEventListener('DOMContentLoaded',()=>{
 if($('loginPage'))$('loginPage').classList.remove('hidden');
 if($('app'))$('app').classList.add('hidden');
 const btn=$('loginBtn');
 if(btn){btn.type='button';btn.addEventListener('click',e=>{e.preventDefault();login();},false)}
 const pass=$('password');
 if(pass)pass.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();login();}});
 try{
  const raw=storageGet('aurion_session_v1','');
  if(raw){
   const saved=JSON.parse(raw);
   if(saved&&saved.id){
    currentUser=saved;
    $('loginPage').classList.add('hidden');
    $('app').classList.remove('hidden');
    setHeader();renderNav();renderDashboard();showDashboard();
   }
  }
 }catch(e){try{localStorage.removeItem('aurion_session_v1')}catch(_){} console.warn('Session restore failed',e)}
});
